def count_element_freq(tup):
    from collections import defaultdict

    def flatten_and_count(element):
        if isinstance(element, tuple):
            for item in element:
                flatten_and_count(item)
        else:
            freq[element] += 1

    freq = defaultdict(int)
    flatten_and_count(tup)
    return dict(freq)
```

